return items.map(item => {
  let score = 0;

  // "output" enthält den Score als Text, z.B. "**Gesamtscore:** 111"
  if (typeof item.json.output === 'string') {
    const match = item.json.output.match(/\*\*Gesamtscore:\*\*\s*(\d+)/);
    score = match ? parseInt(match[1], 10) : 0;
  } else {
    score = item.json.Gesamtscore || item.json.categoryScore || 0;
  }

  let category;

  if (score >= 100 && score <= 117) {
    category = 'sehr_gut';
  } else if (score >= 90 && score <= 109) {
    category = 'solide';
  } else if (score >= 65 && score <= 89) {
    category = 'schwach';
  } else {
    category = 'kritisch';
  }

  return {
    json: {
      ...item.json,
      score,
      category,
    }
  };
});

